    private void thenV1PinIsCreated() {
        assertNotNull(this.v1Pin);
        assertTrue(this.v1Pin instanceof LibGpiodV1Pin);
    }

    private void thenV1PinHasCorrectParameters(String pinName, int pinTerminal, KuraGPIODirection direction,
            KuraGPIOMode mode, KuraGPIOTrigger trigger) {
        assertEquals(pinName, this.v1Pin.getName());
        assertEquals(pinTerminal, this.v1Pin.getIndex());
        assertEquals(direction, this.v1Pin.getDirection());
        assertEquals(mode, this.v1Pin.getMode());
        assertEquals(trigger, this.v1Pin.getTrigger());
    }

    private void thenV1PinIsNotOpen() {
        assertFalse(v1Pin.isOpen());
    }

    private void thenV1PinIsOpen() {
        assertTrue(v1Pin.isOpen());
    }

    private void thenV1PinValueIsBoolean() {
        assertNotNull(this.v1PinValue);
        assertTrue(this.v1PinValue instanceof Boolean);
    }

    private void thenV1PinValueReadIs(boolean expectedValue) {
        assertEquals(expectedValue, this.v1PinValue);
    }

    private void thenV1PinIndexIs(int expectedIndex) {
        assertEquals(expectedIndex, this.v1Pin.getIndex());
    }

    private void thenMessageIs(String expectedMessage) {
        assertEquals(expectedMessage, this.message);
    }
    
    private void thenListenerIsInvockedTimes(int times) {
		verify(this.pinStatusListener, times(times)).pinStatusChange(anyBoolean());
	}

